def _now_iso() -> str:
    return datetime.datetime.now(datetime.timezone.utc).isoformat()


def _duration_str(start_iso: Optional[str], end_iso: Optional[str] = None) -> str:
    """Human-readable duration between two ISO timestamps."""
    try:
        start = datetime.datetime.fromisoformat((start_iso or "").replace("Z", "+00:00"))
        end_str = end_iso or _now_iso()
        end = datetime.datetime.fromisoformat(end_str.replace("Z", "+00:00"))
        secs = int((end - start).total_seconds())
        if secs < 0:
            return "—"
        if secs < 60:
            return f"{secs}s"
        if secs < 3600:
            return f"{secs // 60}m {secs % 60}s"
        h, rem = divmod(secs, 3600)
        return f"{h}h {rem // 60}m"
    except Exception:
        return "—"


def _ts_display(iso: Optional[str]) -> str:
    if not iso:
        return "—"
    try:
        dt = datetime.datetime.fromisoformat(iso.replace("Z", "+00:00"))
        return dt.strftime("%Y-%m-%d %H:%M UTC")
    except Exception:
        return iso[:16] if iso and len(iso) >= 16 else "—"


def _parse_markdown_table(text: str) -> list[dict]:
    """Parse a simple markdown table into a list of dicts."""
    lines = [l.strip() for l in text.strip().splitlines() if l.strip()]
    if len(lines) < 2:
        return []
    # Find header row (first row with |)
    header_line = None
    data_start = 0
    for i, line in enumerate(lines):
        if "|" in line and header_line is None:
            header_line = line
            data_start = i + 2  # skip separator row
            break
    if not header_line:
        return []
    headers = [h.strip() for h in header_line.split("|") if h.strip()]
    rows = []
    for line in lines[data_start:]:
        if not line.startswith("|"):
            continue
        cells = [c.strip() for c in line.split("|") if c.strip()]
        if len(cells) >= len(headers):
            rows.append(dict(zip(headers, cells[:len(headers)])))
    return rows


def _parse_all_markdown_tables(text: str) -> list[dict]:
    """Parse ALL markdown tables from text (not just the first).

    Handles documents with multiple tables separated by headings or prose.
    Returns combined rows from all tables.
    """
    all_rows = []
    lines = text.strip().splitlines()
    i = 0
    while i < len(lines):
        line = lines[i].strip()
        # Detect table header: row with | followed by separator row with ---
        if "|" in line and (i + 1 < len(lines)) and "---" in lines[i + 1]:
            headers = [h.strip() for h in line.split("|") if h.strip()]
            i += 2  # skip header + separator
            while i < len(lines) and "|" in lines[i]:
                cells = [c.strip() for c in lines[i].strip().split("|") if c.strip()]
                if len(cells) >= len(headers):
                    all_rows.append(dict(zip(headers, cells[:len(headers)])))
                i += 1
            continue
        i += 1
    return all_rows


def _extract_heading(text: str, level: int = 1) -> str:
    """Extract first heading of given level from markdown text."""
    prefix = "#" * level + " "
    for line in text.splitlines():
        if line.strip().startswith(prefix):
            return line.strip()[len(prefix):].strip()
    return ""


def _count_files(directory: Path, pattern: str) -> int:
    """Count files matching a glob pattern in a directory."""
    if not directory.exists():
        return 0
    return len(list(directory.glob(pattern)))


def _extract_section(text: str, heading: str) -> str:
    """Extract content under a specific heading until next heading of same/higher level."""
    lines = text.splitlines()
    in_section = False
    section_lines = []
    heading_level = 0
    for line in lines:
        stripped = line.strip()
        if stripped.startswith("#"):
            hashes = len(stripped) - len(stripped.lstrip("#"))
            title = stripped.lstrip("#").strip().lower()
            if title == heading.lower():
                in_section = True
                heading_level = hashes
                continue
            elif in_section and hashes <= heading_level:
                break
        if in_section:
            section_lines.append(line)
    return "\n".join(section_lines).strip()

